SELECT fdd.id, fdd.create_time, fdd.update_time, fdd.create_user_name, fdd.create_user_id, fdd.update_user_name, fdd.update_user_id, fdd.version, fdd.is_deleted, fdd.main_id, fdd.asin, fdd.msku, fdd.fn_sku, fdd.sku_no, fdd.product_name, fdd.stock_sku, fdd.declare_qty, fdd.plan_qty, fdd.delivery_qty, fdd.is_combination, fdd.net_weight, fdd.product_size_length, fdd.product_size_width, fdd.product_size_height, fdd.source_detail_id, fdd.warehouse_location, fdd.receive_date, fd.approve_status FROM first_mile_delivery fd INNER JOIN first_mile_delivery_detail fdd ON fd.id = fdd.main_id AND fdd.is_deleted = FALSE WHERE fd.is_deleted = FALSE
AND fdd.source_detail_id IN
#{sourceDetailId}
